cat > /tmp/validate-model.mjs << 'EOF'
import { chromium } from '/workspace/node_modules/playwright/index.mjs';
import fs from 'node:fs';

const browser = await chromium.launch({ headless: true });
const ctx = await browser.newContext({ acceptDownloads: true, viewport: { width: 1440, height: 900 } });
const page = await ctx.newPage();
const pageErrors = [];
page.on('pageerror', (e) => pageErrors.push(String(e)));

await page.goto('http://localhost:5173/', { waitUntil: 'networkidle', timeout: 60000 });
await page.waitForTimeout(1500);

// Inspect canvas/workspace markup before interaction
const canvasInfo = await page.evaluate(() => {
  const el = [...document.querySelectorAll('*')].find(e => e.textContent?.trim() === 'Ergänzen Sie eines der folgenden Elemente in die Arbeitsfläche:');
  return el ? { tag: el.tagName, cls: el.className.toString().slice(0,120), parentCls: el.parentElement?.className.toString().slice(0,120) } : null;
});
console.log('EMPTY_HINT_EL:', JSON.stringify(canvasInfo));

// Click module in palette
await page.getByRole('button', { name: 'Einzeiliges Textfeld' }).first().click();
await page.waitForTimeout(1000);

// Find any delete/close actions now available on canvas items
const afterClick = await page.evaluate(() => {
  const btns = [...document.querySelectorAll('button')].map(b => (b.getAttribute('aria-label') || b.getAttribute('title') || b.textContent?.trim() || '').slice(0,60));
  return btns;
});
console.log('BUTTONS_AFTER_CLICK:', JSON.stringify(afterClick));

// Test the documented "JSON herunterladen" flow (uses designerRef.getModel())
const [download] = await Promise.all([
  page.waitForEvent('download', { timeout: 10000 }).catch(() => null),
  page.getByRole('button', { name: 'JSON herunterladen' }).first().click(),
]);
if (download) {
  const p = '/tmp/downloaded-form.json';
  await download.saveAs(p);
  const content = fs.readFileSync(p, 'utf8');
  console.log('DOWNLOAD_FILENAME:', download.suggestedFilename());
  console.log('DOWNLOAD_CONTENT:', content.slice(0, 2500));
} else {
  console.log('NO_DOWNLOAD_TRIGGERED');
}
console.log('PAGE_ERRORS:', JSON.stringify(pageErrors));
await browser.close();
EOF
node /tmp/validate-model.mjs; echo "EXIT: $?"

